def order(item, qty=1, *, express=False, **extras):
    total = qty * extras.get('price', 10)
    if express:
        total += 5
    return qty, total

print(order('pen'))                    # (1, 10)
print(order('pen', 3))                 # (3, 30)
print(order('pen', 3, express=True, price=2))  # (3, 11)

def total(*nums):
    return sum(nums)

print(total(1, 2, 3))                  # 6
print(total(*[4, 5], 6))               # 15

def apply(f, value):
    return f(value)

print(apply(str.upper, 'hello'))       # HELLO

