practice.solution:
def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 and b == 0:
        return 0
    return a // gcd(a, b) * b

n = int(input())
for _ in range(n):
    a, b = map(int, input().split())
    print(gcd(a, b), lcm(a, b))

